// The sandbox's entry: one request is one judgment. The site (and the kit)
// sends { submission, seeds, capture, network } and gets back
// { verdict, logs } or { error, logs }, with a test's requests when it
// answered them (prelude.mjs). The secret seed never comes here, only this
// submission's two seeds (seeds.mjs). { describe: true } asks what
// judge.js exports besides judge — `network` (协议第 9 节), and from the
// third version `meta`, `params`, `hongbao` and whether it has `check`
// (docs/judge-square-design.md §3, §4), from the fourth whether it has
// `setup` (docs/judge-page-design.md §2) — for a deploy to check.
// { check: { params, hongbao, now } } runs check(params, hongbao) once;
// { setup: { params, hongbao, now, seed } } runs setup(params, hongbao)
// once, at opening, Math.random() drawn from `seed` (seeds.mjs).
// Fourth protocol: an answer's view.data is one level below its state.
// Fifth (docs/multi-prize-design.md §3): submission.player is this
// person's own; an answer's others[i].view.data is three below its state.
import { begin, finish } from "./prelude.mjs";
import { createRandom } from "./random.mjs";
import { createTools } from "./tools.mjs";
import { LIMITS, nestsDeeper } from "./verdict.mjs";

/** The exports a deploy reads, as data. */
const DESCRIBED = ["network", "meta", "params", "hongbao"];
/** check() has no submission to seed it: Math.random() is the same for all. */
const CHECK_SEED = "0".repeat(64);

// The sender's code loads at the first judgment, so the prelude has always
// fixed the time, Math.random() and console before any of its lines run.
let loading;

function reply(body) {
  return new Response(JSON.stringify(body), {
    headers: { "content-type": "application/json" },
  });
}

function explain(error) {
  if (error instanceof Error)
    return `${error.name}: ${error.message}`.slice(0, 500);
  return String(error).slice(0, 500);
}

/**
 * What judge.js exports besides judge, as JSON for the site to read: each
 * of DESCRIBED (null when absent; listed in `unreadable` when it does not
 * turn into JSON) and whether `check` is a function.
 */
function exported(code) {
  const answer = { unreadable: [] };
  for (const name of DESCRIBED) {
    if (code[name] === undefined) {
      answer[name] = null;
      continue;
    }
    try {
      answer[name] = JSON.parse(JSON.stringify(code[name])) ?? null;
    } catch {
      answer[name] = null;
      answer.unreadable.push(name);
    }
  }
  for (const name of ["check", "setup"])
    answer[name] =
      code[name] === undefined ? null : typeof code[name] === "function";
  return answer;
}

/** The JSON parts of an answer, where they are, deepest first. */
function partsOf(answer) {
  const others = Array.isArray(answer.others) ? answer.others : [];
  return [
    ...others.flatMap((other, index) => [
      [`others 第 ${index + 1} 项的 view.data`, other?.view?.data],
      [`others 第 ${index + 1} 项的 state`, other?.state],
    ]),
    ["player.view.data", answer.player?.view?.data],
    ["player.state", answer.player?.state],
    ["view.data", answer.view?.data],
    ["state", answer.state],
  ];
}

/**
 * An answer nested too deep for JSON.stringify here on one machine and
 * not another: the same refusal for all (verdict.mjs, state's depth), or
 * null. `name` is what it answered for ("" for judge()).
 */
function tooDeep(answer, name) {
  if (
    answer === null ||
    typeof answer !== "object" ||
    !nestsDeeper(answer, LIMITS.stateDepth + 4)
  )
    return null;
  const [where] =
    partsOf(answer).find(([, part]) => nestsDeeper(part, LIMITS.stateDepth)) ??
    [];
  const detail = where
    ? `${where} 嵌套超过 ${LIMITS.stateDepth} 层`
    : "返回的值转不成 JSON";
  return { kind: "invalid", detail: name ? `${name} 的 ${detail}` : detail };
}

/** setup(params, hongbao) once at opening: its answer, or how it failed. */
async function runSetup(code, { params, hongbao, now, seed }, capture) {
  if (typeof code.setup !== "function") return reply({ answer: null });
  begin({ now, next: createRandom(seed).api.next, capture });
  let answer;
  try {
    answer = await code.setup(
      structuredClone(params),
      structuredClone(hongbao),
    );
  } catch (error) {
    const { logs } = finish();
    return reply({ error: { kind: "threw", detail: explain(error) }, logs });
  }
  const { logs } = finish();
  const deep = tooDeep(answer, "setup");
  if (deep) return reply({ error: deep, logs });
  try {
    return reply({ answer: answer ?? null, logs });
  } catch {
    return reply({
      error: { kind: "invalid", detail: "setup 返回的值转不成 JSON" },
      logs,
    });
  }
}

/** check(params, hongbao) once: its answer, or how it failed. */
async function runCheck(code, { params, hongbao, now }, capture) {
  if (typeof code.check !== "function") return reply({ answer: [] });
  begin({ now, next: createRandom(CHECK_SEED).api.next, capture });
  let answer;
  try {
    answer = await code.check(
      structuredClone(params),
      structuredClone(hongbao),
    );
  } catch (error) {
    const { logs } = finish();
    return reply({ error: { kind: "threw", detail: explain(error) }, logs });
  }
  const { logs } = finish();
  try {
    return reply({ answer: answer ?? null, logs });
  } catch {
    return reply({
      error: { kind: "invalid", detail: "check 返回的值转不成 JSON" },
      logs,
    });
  }
}

export default {
  async fetch(request) {
    const { submission, seeds, capture, network, describe, check, setup } =
      await request.json();
    let code;
    try {
      loading ??= import("./judge.js");
      code = await loading;
    } catch (error) {
      return reply({ error: { kind: "load", detail: explain(error) } });
    }
    if (typeof code.judge !== "function")
      return reply({
        error: { kind: "no-judge", detail: "judge.js 没有导出 judge 函数" },
      });
    if (describe === true) return reply(exported(code));
    if (check) return runCheck(code, check, capture);
    if (setup) return runSetup(code, setup, capture);
    const { tools, next } = createTools(submission, seeds);
    begin({ now: submission.now, next, capture, network: network ?? null });
    let verdict;
    try {
      verdict = await code.judge(structuredClone(submission), tools);
    } catch (error) {
      const { logs, ...asked } = finish();
      return reply({
        error: { kind: "threw", detail: explain(error) },
        logs,
        ...asked,
      });
    }
    const { logs, ...asked } = finish();
    const deep = tooDeep(verdict, "");
    if (deep) return reply({ error: deep, logs, ...asked });
    try {
      return reply({ verdict, logs, ...asked });
    } catch {
      return reply({
        error: { kind: "invalid", detail: "返回的值转不成 JSON" },
        logs,
        ...asked,
      });
    }
  },
};

prelude.mjs:
// The first module the sandbox evaluates, before the sender's code: it fixes
// what that code can lean on (协议第 4.3、4.4、9 节). Time, Math.random()
// and fetch() only exist while judge() runs: at the top of the file they
// would differ from call to call.
import {
  NETWORK_LIMITS,
  NETWORK_REASONS,
  networkError,
  requestProblem,
} from "./network.mjs";

const RealDate = Date;
let pinned = null;
let random = null;
let sink = null;

function notYet(what) {
  throw new Error(`${what} 只能在 judge 里用`);
}

class JudgeDate extends RealDate {
  constructor(...args) {
    if (args.length === 0 && pinned === null)
      throw new Error("new Date() 只能在 judge 里用");
    if (args.length > 0) super(...args);
    else super(pinned);
  }

  static now() {
    return pinned === null ? notYet("Date.now()") : pinned;
  }
}
globalThis.Date = JudgeDate;
Math.random = () => (random === null ? notYet("Math.random()") : random());

// Data could pass between 红包 through the cache: there is none here.
try {
  delete globalThis.caches;
} catch {}
if ("caches" in globalThis) {
  try {
    Object.defineProperty(globalThis, "caches", { value: undefined });
  } catch {}
}

function show(value) {
  if (typeof value === "string") return value;
  try {
    return JSON.stringify(value) ?? String(value);
  } catch {
    return String(value);
  }
}

// On the site console output is dropped; the kit asks for it.
for (const name of [
  "log",
  "info",
  "warn",
  "error",
  "debug",
  "trace",
  "dir",
  "table",
])
  console[name] = (...args) => {
    if (sink && sink.length < 200)
      sink.push(
        `${name === "log" ? "" : `${name}: `}${args.map(show).join(" ")}`.slice(
          0,
          2000,
        ),
      );
  };

// fetch() (协议第 9 节): only to the addresses in `network`, a few times a
// judgment. On the site it goes out through the gateway, which holds the
// same rules again where the code cannot reach; in tests it is answered
// from what the test wrote, never the network. Failing, it throws as
// fetch does, a TypeError saying why.
const realFetch = globalThis.fetch.bind(globalThis);
/** During judge(): null, or `{ list, mode, answers, used, requests }`. */
let net = null;
let judging = false;
const decoder = new TextDecoder();
const encoder = new TextEncoder();

/** A written answer (tests.json's `fetch`) to the request it fits. */
function sameRequest(answer, method, address) {
  try {
    return (
      (answer.method ?? "GET") === method &&
      new URL(answer.url).href === address
    );
  } catch {
    return false;
  }
}

function answered(answer) {
  if (answer.error === "timeout") throw networkError(NETWORK_REASONS.timeout);
  if (answer.error === "unreachable")
    throw networkError(NETWORK_REASONS.unreachable);
  if (answer.error === "too-big")
    throw networkError(NETWORK_REASONS.responseTooBig);
  const json = Object.hasOwn(answer, "json");
  const body = json
    ? JSON.stringify(answer.json)
    : typeof answer.text === "string"
      ? answer.text
      : "";
  if (encoder.encode(body).length > NETWORK_LIMITS.responseBytes)
    throw networkError(NETWORK_REASONS.responseTooBig);
  const headers = new Headers(answer.headers ?? {});
  if (json && !headers.has("content-type"))
    headers.set("content-type", "application/json");
  const status = answer.status ?? 200;
  // A body is not allowed with these statuses.
  const empty = [101, 204, 205, 304].includes(status);
  return new Response(empty ? null : body, { status, headers });
}

async function judgeFetch(input, init) {
  if (!judging) throw networkError(NETWORK_REASONS.ended);
  if (net === null || net.list === null)
    throw networkError(NETWORK_REASONS.none);
  const request = new Request(input, init);
  const method = request.method.toUpperCase();
  const address = request.url;
  const body =
    method === "GET" || method === "HEAD"
      ? new Uint8Array(0)
      : new Uint8Array(await request.arrayBuffer());
  const problem = requestProblem(
    {
      method,
      address,
      headers: [...request.headers.keys()],
      bodyBytes: body.length,
    },
    net.list,
  );
  if (problem) throw networkError(problem);
  if (net.requests.length >= NETWORK_LIMITS.requests)
    throw networkError(NETWORK_REASONS.tooMany);
  const asked = {
    method,
    url: address,
    ...(body.length > 0 ? { body: decoder.decode(body) } : {}),
  };
  net.requests.push(asked);
  if (net.mode === "mock") {
    const index = net.answers.findIndex(
      (answer, at) => !net.used.has(at) && sameRequest(answer, method, address),
    );
    if (index < 0) {
      asked.unanswered = true;
      throw networkError(`测试里没写这个请求的返回：${method} ${address}`);
    }
    net.used.add(index);
    if (request.signal.aborted) throw request.signal.reason;
    return answered(net.answers[index]);
  }
  const response = await realFetch(address, {
    method,
    headers: request.headers,
    ...(body.length > 0 ? { body } : {}),
    redirect: "manual",
    signal: request.signal,
  });
  // The gateway turned it down: why, in its words.
  const refused = response.headers.get("x-hb-refused");
  if (refused !== null) throw networkError(decodeURIComponent(refused));
  return response;
}

// Wherever fetch is found, it is this one.
for (
  let scope = globalThis;
  scope !== null;
  scope = Object.getPrototypeOf(scope)
)
  if (Object.hasOwn(scope, "fetch"))
    try {
      Object.defineProperty(scope, "fetch", {
        value: judgeFetch,
        writable: false,
        configurable: false,
      });
    } catch {}

/**
 * Before judge(): the time, Math.random()'s stream, whether to keep console
 * output, and the network: null, or the list judge.js exports (null when it
 * exports none) with the mode — `mock` answering from `answers` (a
 * test's), `live` going out.
 */
export function begin({ now, next, capture, network = null }) {
  pinned = now;
  random = next;
  sink = capture ? [] : null;
  net =
    network === null
      ? null
      : {
          list: network.list,
          mode: network.mode,
          answers: network.answers ?? [],
          used: new Set(),
          requests: [],
        };
  judging = true;
}

/**
 * After judge(): the console output kept, if any, and with a test's
 * answers what was asked (`requests`, those with no answer marked
 * `unanswered`) and which answers went unused.
 */
export function finish() {
  const logs = sink;
  const asked = net?.mode === "mock" ? net : null;
  pinned = null;
  random = null;
  sink = null;
  net = null;
  judging = false;
  return {
    logs: logs ?? undefined,
    ...(asked
      ? {
          requests: asked.requests,
          unused: asked.answers
            .map((answer, index) => ({ answer, index }))
            .filter(({ index }) => !asked.used.has(index))
            .map(({ answer }) => ({
              method: answer.method ?? "GET",
              url: answer.url,
            })),
        }
      : {}),
  };
}

